import {
    ts,
    FluentDiagnostic,
    type Product,
    type Diagnostics as IDiagnostics,
    Diagnostic,
    hasDirective,
} from '@servicenow/sdk-build-core'

function getOriginalNode(source: Product | ts.Node): ts.Node {
    return ts.Node.isNode(source) ? source : source.getOriginalNode()
}

export class Diagnostics implements IDiagnostics {
    private diagnostics: Diagnostic[] = []

    error(source: Product | ts.Node, message: string): void {
        this.add(new FluentDiagnostic(getOriginalNode(source), message, { level: Diagnostic.Level.Error }))
    }

    warn(source: Product | ts.Node, message: string): void {
        this.add(new FluentDiagnostic(getOriginalNode(source), message, { level: Diagnostic.Level.Warn }))
    }

    info(source: Product | ts.Node, message: string): void {
        this.add(new FluentDiagnostic(getOriginalNode(source), message, { level: Diagnostic.Level.Info }))
    }

    hint(source: Product | ts.Node, message: string): void {
        this.add(new FluentDiagnostic(getOriginalNode(source), message, { level: Diagnostic.Level.Hint }))
    }

    add(diagnostic: Diagnostic): void {
        if (isIgnored(diagnostic)) {
            return
        }

        // TODO: Optimize this lookup - maybe encode the values into a key or hash
        if (
            this.diagnostics.some(
                (d) =>
                    d.message === diagnostic.message &&
                    d.code === diagnostic.code &&
                    d.level === diagnostic.level &&
                    d.source === diagnostic.source &&
                    d.position.start === diagnostic.position.start &&
                    d.position.end === diagnostic.position.end &&
                    d.file.getFilePath() === diagnostic.file.getFilePath()
            )
        ) {
            return
        }

        this.diagnostics.push(diagnostic)
    }

    getAll(file?: string): Diagnostic[] {
        return file ? this.diagnostics.filter((d) => d.file.getFilePath() === file) : this.diagnostics
    }

    clear(file?: string): void {
        this.diagnostics = file ? this.diagnostics.filter((d) => d.file.getFilePath() !== file) : []
    }

    getWarnings(file?: string): Diagnostic[] {
        return this.getAll(file).filter((d) => d.level === Diagnostic.Level.Warn)
    }

    hasErrors(file?: string): boolean {
        return this.getAll(file).some((d) => d.level === Diagnostic.Level.Error)
    }

    getErrors(file?: string): Diagnostic[] {
        return this.getAll(file).filter((d) => d.level === Diagnostic.Level.Error)
    }
}

function isIgnored(diagnostic: Diagnostic): boolean {
    return diagnostic instanceof FluentDiagnostic && hasDirective(diagnostic.node, '@fluent-ignore')
}
